hidden-surface-removal.pseudocode:
def z_buffer(polygons, W, H):
    depth = [[INF] * W for _ in range(H)]  # 깊이 버퍼
    frame = [[BG] * W for _ in range(H)]  # 색 버퍼
    for poly in polygons:
        # 다각형이 덮는 픽셀과 그 점의 깊이 z
        for x, y, z in rasterize(poly):
            if z < depth[y][x]:  # 더 가까우면 갱신
                depth[y][x] = z
                frame[y][x] = shade(poly, x, y)
    return frame  # 그리는 순서와 무관

hierarchical-clustering.pseudocode:
def agglomerative(points, dist, linkage):
    clusters = [[p] for p in points]  # 각 점이 군집
    merges = []
    while len(clusters) > 1:
        best, pair = None, None
        for i in range(len(clusters)):
            for j in range(i + 1, len(clusters)):
                d = linkage(clusters[i], clusters[j], dist)
                if best is None or d < best:
                    best, pair = d, (i, j)
        i, j = pair  # 가장 가까운 두 군집 병합
        merges.append((clusters[i], clusters[j], best))
        clusters[i] = clusters[i] + clusters[j]
        del clusters[j]
    return merges  # 병합 순서 = 덴드로그램

hierarchical-navigable-small-world.pseudocode:
def hnsw_search(q, ep, top, ef, k):
    for lc in range(top, 0, -1):  # 상위 희소층: 탐욕 하강
        ep = search_layer(q, ep, 1, lc)[0]
    return search_layer(q, ep, ef, 0)[:k]  # 0층: ef개 탐색

def search_layer(q, ep, ef, lc):
    d = lambda v: dist(q, v)
    visited, cand, best = {ep}, [ep], [ep]
    while cand:
        c = min(cand, key=d)  # 가장 가까운 후보 확장
        cand.remove(c)
        if d(c) > d(best[-1]):  # best는 거리순 유지
            break  # 더 가까워질 수 없음 → 종료
        for nb in neighbors(c, lc):
            if nb in visited:
                continue
            visited.add(nb)
            if len(best) < ef or d(nb) < d(best[-1]):
                cand.append(nb)
                best = sorted(best + [nb], key=d)[:ef]
    return best  # 거리순 상위 ef개

hill-climbing.pseudocode:
def hill_climbing(start, neighbors, score):
    current = start
    while True:
        # 이웃 중 평가값 최대 선택
        best = max(neighbors(current), key=score,
                   default=None)
        if best is None or score(best) <= score(current):
            return current  # 더 나은 이웃 없음 → 정지
        current = best  # 더 좋은 이웃으로만 이동
